const input = $json;

function requiredText(name) {
  const value = input[name];

  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`Champ texte manquant ou invalide : ${name}`);
  }

  return value.trim();
}

function requiredNumber(name, strictlyPositive = false) {
  const value = input[name];

  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`Champ numérique manquant ou invalide : ${name}`);
  }

  if (strictlyPositive ? value <= 0 : value < 0) {
    throw new Error(
      `${name} doit être ${strictlyPositive ? 'supérieur à zéro' : 'positif ou nul'}.`
    );
  }

  return value;
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

const asset = requiredText('asset');
const ticker = requiredText('ticker');
const type = requiredText('type').toLowerCase();
const date = requiredText('date');

if (!['buy', 'sell'].includes(type)) {
  throw new Error('type doit être "buy" ou "sell".');
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error('date doit respecter le format YYYY-MM-DD.');
}

const parsedDate = new Date(`${date}T00:00:00.000Z`);

if (
  !Number.isFinite(parsedDate.getTime()) ||
  parsedDate.toISOString().slice(0, 10) !== date
) {
  throw new Error('La date fournie est invalide.');
}

const quantity = requiredNumber('quantity', true);
const price = requiredNumber('price', true);
const fees = requiredNumber('fees');
const ttfPercent = requiredNumber('ttfPercent');

if (ttfPercent > 100) {
  throw new Error('ttfPercent ne doit pas dépasser 100.');
}

const grossAmount = quantity * price;
const amount = roundMoney(grossAmount);
const ttf = roundMoney(grossAmount * ttfPercent / 100);

return {
  json: {
    asset,
    ticker,
    type,
    date,
    quantity,
    price,
    fees,
    ttfPercent,
    amount,
    ttf,
    createdAt: Date.now(),
    dateObj: parsedDate.toISOString()
  }
};

